// SPDX-License-Identifier: GPL-3.0

pragma solidity 0.8.15;

import {TickMath} from "./v3-core-0.8/contracts/libraries/TickMath.sol";

import {LiquidityAmounts} from "./v3-periphery-0.8/contracts/libraries/LiquidityAmounts.sol";

import "./base/Structs.sol";
import {IBunniHub} from "./interfaces/IBunniHub.sol";
import {IBunniLens} from "./interfaces/IBunniLens.sol";
import {IBunniToken} from "./interfaces/IBunniToken.sol";

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title BunniLens
/// @author zefram.eth
/// @notice Helper functions for fetching info about Bunni positions
contract BunniLensV2 is IBunniLens, Ownable {
    uint256 internal constant SHARE_PRECISION = 1e18;

    IBunniHub public immutable override hub;

    //token address to bunniKey
    mapping (address => BunniKey) private tokenToBunniKeys;
    //bunniKey to token address
    mapping (bytes32 => address) private bunniKeyToToken;
    //pair address to bunniKey
    mapping (address => BunniKey[]) private pairToBunniKeys;

    constructor(IBunniHub hub_) {
        hub = hub_;
    }

    function addKey(BunniKey calldata key, address pair, address token) external onlyOwner {
        tokenToBunniKeys[token] = key;
        bytes32 bunniKeyHash = keccak256(abi.encode(key));
        bunniKeyToToken[bunniKeyHash] = token;
        pairToBunniKeys[pair].push(key);
    }

    function removeKey(uint index, address pair, address token) external onlyOwner {

        //deletes index by overwriting it with last element and popping array
        BunniKey[] storage pairData = pairToBunniKeys[pair];
        require(index < pairData.length, "OOB");
        pairData[index] = pairData[pairData.length - 1];
        pairData.pop();

        delete tokenToBunniKeys[token];
    }

    /// @inheritdoc IBunniLens
    function pricePerFullShare(BunniKey calldata key)
        external
        view
        virtual
        override
        returns (
            uint128 liquidity,
            uint256 amount0,
            uint256 amount1
        )
    {
        IBunniToken shareToken = hub.getBunniToken(key);
        uint256 existingShareSupply = shareToken.totalSupply();
        if (existingShareSupply == 0) {
            return (0, 0, 0);
        }

        (liquidity, , , , ) = key.pool.positions(
            keccak256(
                abi.encodePacked(address(hub), key.tickLower, key.tickUpper)
            )
        );
        // liquidity is uint128, SHARE_PRECISION uses 60 bits
        // so liquidity * SHARE_PRECISION can't overflow 256 bits
        liquidity = uint128(
            (liquidity * SHARE_PRECISION) / existingShareSupply
        );
        (amount0, amount1) = _getReserves(key, liquidity);
    }

    /// @inheritdoc IBunniLens
    function getReserves(BunniKey calldata key)
        external
        view
        override
        returns (uint112 reserve0, uint112 reserve1)
    {
        (uint128 existingLiquidity, , , , ) = key.pool.positions(
            keccak256(
                abi.encodePacked(address(hub), key.tickLower, key.tickUpper)
            )
        );
        return _getReserves(key, existingLiquidity);
    }

    function getBunniVault(address pool, uint256 index) public view returns (BunniKey memory key, IBunniToken token) {
        key = pairToBunniKeys[pool][index];
        token = IBunniToken(getTokenForBunniKey(key));
    }

    function getBunniVaults(address pool) public view returns(BunniKey[] memory keys, IBunniToken[] memory tokens) {

        BunniKey[] memory allKeys = pairToBunniKeys[pool];
        tokens = new IBunniToken[](allKeys.length);
        unchecked {
            for(uint i = 0; i < allKeys.length; ++i) {
                BunniKey memory key = allKeys[i];
                keys[i] = key;
                tokens[i] = IBunniToken(getTokenForBunniKey(key));
            }
        }
    }

    function getBunniKeyForToken(address token) public view returns (BunniKey memory key) {
        key = tokenToBunniKeys[token];
    }

    function getTokenForBunniKey(BunniKey memory key) public view returns (address token) {
        bytes32 bunniKeyHash = keccak256(abi.encode(key));
        token = bunniKeyToToken[bunniKeyHash];
    }

    /// @notice Cast a uint256 to a uint112, revert on overflow
    /// @param y The uint256 to be downcasted
    /// @return z The downcasted integer, now type uint112
    function _toUint112(uint256 y) internal pure returns (uint112 z) {
        require((z = uint112(y)) == y);
    }

    /// @dev See getReserves
    function _getReserves(BunniKey calldata key, uint128 existingLiquidity)
        internal
        view
        returns (uint112 reserve0, uint112 reserve1)
    {
        (uint160 sqrtRatioX96, , , , , , ) = key.pool.slot0();
        uint160 sqrtRatioAX96 = TickMath.getSqrtRatioAtTick(key.tickLower);
        uint160 sqrtRatioBX96 = TickMath.getSqrtRatioAtTick(key.tickUpper);
        (uint256 amount0, uint256 amount1) = LiquidityAmounts
            .getAmountsForLiquidity(
                sqrtRatioX96,
                sqrtRatioAX96,
                sqrtRatioBX96,
                existingLiquidity
            );

        reserve0 = _toUint112(amount0);
        reserve1 = _toUint112(amount1);
    }

}

